(5937799, 865743, 104537, '<td valign="top">Great image and gorgeous cat. I notice you used a shiney texture fabric which was a great choice, the cat does not blend into the background.</td>', 'Great image and gorgeous cat. I notice you used a shiney texture fabric which was a great choice, the cat does not blend into the background.', '2010-04-08 18:39:46.000000', NULL, 1),
(5937800, 865498, 104537, '<td valign="top">I really like this, the lighting accentuates the features of the statue. Very nice!</td>', 'I really like this, the lighting accentuates the features of the statue. Very nice!', '2010-04-08 18:40:38.000000', NULL, 1),
