(5945467, 865712, 54446, '<td valign="top">Congratulations on a very well deserved ribbon winner.  This is a very compelling image.  Great use of selective focus with wonderful clarity and detail.</td>', 'Congratulations on a very well deserved ribbon winner.  This is a very compelling image.  Great use of selective focus with wonderful clarity and detail.', '2010-04-14 06:20:41.000000', NULL, 0),
